import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """k-shortest-path candidates + greedy marginal-union-cost assignment.

    For each destination we enumerate several candidate contiguous paths
    (k best via nx.shortest_simple_paths on the directed cost graph).
    We then assign destinations to candidates greedily, each time picking
    the candidate whose edge set adds the least *marginal* cost to the
    union of already-chosen edges (shared relay edges are paid once).
    Multiple randomized orderings (restarts) are tried, followed by a
    swap-polish local search; the best union-cost assignment wins.

    Continuity is guaranteed: every candidate is a verbatim node path,
    so consecutive recorded edges always chain src -> ... -> dst.
    """
    import random

    def weight_fn(u, v, d):
        c = d.get("cost")
        return c if c is not None else float("inf")

    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    targets = [d for d in dsts if d != src]
    for d in dsts:
        if d == src:
            for j in range(num_partitions):
                bc_topology.set_dst_partition_paths(d, j, [])

    if not targets:
        return bc_topology

    # 1) Candidate pool: up to K cheapest paths per destination.
    K = 8
    candidates = {}  # dst -> list of (path_nodes, edge_set, path_cost)
    for d in targets:
        cands = []
        try:
            gen = nx.shortest_simple_paths(G, src, d, weight=weight_fn)
            for p in gen:
                eset = {(p[i], p[i + 1]) for i in range(len(p) - 1)}
                pcost = sum(weight_fn(p[i], p[i + 1], G[p[i]][p[i + 1]])
                            for i in range(len(p) - 1))
                cands.append((p, eset, pcost))
                if len(cands) >= K:
                    break
        except nx.NetworkXException:
            pass
        if not cands:
            # Dijkstra fallback (single candidate)
            try:
                p = nx.dijkstra_path(G, src, d, weight=weight_fn)
                eset = {(p[i], p[i + 1]) for i in range(len(p) - 1)}
                pcost = sum(weight_fn(p[i], p[i + 1], G[p[i]][p[i + 1]])
                            for i in range(len(p) - 1))
                cands.append((p, eset, pcost))
            except nx.NetworkXException:
                cands = [([src, d] if G.has_edge(src, d) else [], set(), 0.0)]
        candidates[d] = cands

    def ecost(e):
        return weight_fn(e[0], e[1], G[e[0]][e[1]])

    def union_cost(assignment):
        """Total cost of union of chosen edges (each edge paid once)."""
        used = set()
        total = 0.0
        for d, ci in assignment.items():
            for e in candidates[d][ci][1]:
                if e not in used:
                    used.add(e)
                    total += ecost(e)
        return total

    # 2) Greedy assignment with randomized restarts.
    def greedy(order):
        assignment = {}
        used = {}
        for d in order:
            best_ci, best_add = 0, float("inf")
            for ci, (p, eset, pcost) in enumerate(candidates[d]):
                add = sum(ecost(e) for e in eset if e not in used)
                if add < best_add:
                    best_add, best_ci = add, ci
            assignment[d] = best_ci
            for e in candidates[d][best_ci][1]:
                used[e] = True
        return assignment

    rng = random.Random(0)
    best_assign = greedy(targets)
    best_cost = union_cost(best_assign)
    for _ in range(6):
        order = targets[:]
        rng.shuffle(order)
        a = greedy(order)
        c = union_cost(a)
        if c < best_cost:
            best_cost, best_assign = c, a

    # 3) Swap polish: single-dst swap to any candidate that lowers cost.
    improved = True
    while improved:
        improved = False
        for d in targets:
            cur = best_assign[d]
            for ci in range(len(candidates[d])):
                if ci == cur:
                    continue
                trial = dict(best_assign)
                trial[d] = ci
                c = union_cost(trial)
                if c < best_cost - 1e-9:
                    best_cost, best_assign = c, trial
                    improved = True
                    break

    # 4) Materialize paths (same path reused across all partitions).
    for d in targets:
        p = candidates[d][best_assign[d]][0]
        edges = [[p[i], p[i + 1], G[p[i]][p[i + 1]]]
                 for i in range(len(p) - 1)]
        for j in range(num_partitions):
            bc_topology.set_dst_partition_paths(d, j, list(edges))

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

